INSERT INTO collection_pages VALUES('da883383431c9bd85bdedfa6a37bc80c1ab47f19bf6e65dad9bce689173c2b1e','2d4f2444c2a2ab48834266ec467d555482ed5679b3927545be73fabe3caf58b4','{"hasNext":false,"items":[{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T14:40:27Z","committedDate":"2026-09-27T14:43:52Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"1ab909d354f1a27b4403df3b6ed73ce710a2ca57"},{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T11:39:15Z","committedDate":"2026-09-27T11:39:15Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"1ef9a8862b361c68ec12b50582a71711ca96e012"},{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T11:36:26Z","committedDate":"2026-09-27T11:36:26Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e"},{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T11:30:07Z","committedDate":"2026-09-27T11:30:07Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"c35889dfa983bdb7bf2687e0ebfd827600367bb0"},{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T11:14:29Z","committedDate":"2026-09-27T11:14:29Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"db1d396449d9a5744c4162891f0724081efb8b5b"},{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T10:31:54Z","committedDate":"2026-09-27T10:31:54Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"5467231afaa728bfa7a2cedd2a3a53049b6790d4"},{"author":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"authoredDate":"2026-09-27T08:57:29Z","committedDate":"2026-09-27T08:57:29Z","committer":{"account":{"login":"lqmnwido","providerType":"User"},"email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"observedAt":"2026-10-09T00:50:34.197Z","repositoryId":1390700202,"sha":"c7d6c6942634f16be48b320dcb34d6a57fb854cd"}],"observedAt":"2026-10-09T00:50:34.197Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/1ab909d354f1a27b4403df3b6ed73ce710a2ca57/comments","commit":{"author":{"date":"2026-09-27T14:40:27Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T14:43:52Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"0.1.1: make the scaffold pass the gates it tells you to run\n\n0.1.0 shipped a package whose generated repositories could not pass their own\nverification. `mvn verify` and `npm run verify` both failed on a module the\ninstaller had just written, and every self-check read the templates without\never building from them, so nothing noticed. Five separate causes, all the\nsame shape — a config that says one thing and a tool that demands another:\n\n  - <springJavaFormat/> is not a Spotless step any more, so the plugin failed\n    while parsing its own configuration. Replaced with palantirJavaFormat and\n    all twelve Java templates reformatted to match.\n  - checkstyle.xml had no DOCTYPE, so it failed before reading a rule.\n  - MinioStorageService imported io.minio.Method, which does not exist; the\n    class is io.minio.http.Method.\n  - The SpotBugs filter was empty while the generated constructors trip\n    EI_EXPOSE_REP2. One entry now, with the conditions that would invalidate it.\n  - .prettierrc.json asked for single quotes and es5 trailing commas while\n    every generated file used double quotes and none.\n\nTwo more that were not code at all:\n\n  - All 97 files in the 0.1.0 tarball were CRLF, because the package was\n    published from a Windows checkout. .gitattributes pins text to LF; a\n    clone with core.autocrlf=true now yields zero CRLF files.\n  - `\"license\": \"UNLICENSED\"` is npm''s way of saying do not use this. Now MIT,\n    with repository, homepage, bugs and publishConfig.access.\n\nThe frontend still emitted a lint warning on every run: the shared UI package\ndeclares `\".\" : { \"import\": \"./dist/index.js\" }` with no `require` and no\n`default`, and the resolver runs in CommonJS mode, so `@2enapps/ui` read as\nunresolved even though webpack builds it. Fixed with `conditions: [\"import\",\n\"default\"]` plus an npm override forcing eslint-import-resolver-node to 0.4.x,\nwhich is the only version that reads subpath `exports` maps at all. `npm run\nverify` is now silent.\n\nAlso in this release:\n\n  - Robust interactivity. --yes, --quiet or CI is a deliberate non-interactive\n    run; otherwise a TTY on stdin *or* stdout counts. An involuntary fallback\n    now prints a loud warning instead of quietly hanging.\n  - The skip reason distinguishes \"you asked for --parts=docs\" from \"we never\n    established who you are\".\n  - VUE_APP_MODUL is namespaced to VUE_APP_{{MODULE_PASCAL_UPPER}}, so two\n    modules on one machine stop deciding each other''s remote origin. The old\n    name is still read as a lower-precedence fallback.\n  - A new self-check asserts the scaffold''s configs agree with each other.\n    Every one of its sixteen assertions is mutation-verified: break the thing,\n    confirm the check complains, put it back. Three of them were silently\n    disarmed by the explanatory comments in the very config files they read,\n    which is why the comment-stripping helpers exist.\n\nVerified end to end from the packed tarball: a fresh --yes --level=full install\nproduces zero CRLF files, `mvn verify` exits 0 with 7 tests passing, and\n`npm run verify` exits 0 with no output.","tree":{"sha":"bde9aaa2f53a1db8f4653790080ea9e253d52925","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/bde9aaa2f53a1db8f4653790080ea9e253d52925"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/1ab909d354f1a27b4403df3b6ed73ce710a2ca57","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/1ab909d354f1a27b4403df3b6ed73ce710a2ca57","node_id":"C_kwDOUuRmqtoAKDFhYjkwOWQzNTRmMWEyN2I0NDAzZGYzYjZlZDczY2U3MTBhMmNhNTc","parents":[{"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/1ef9a8862b361c68ec12b50582a71711ca96e012","sha":"1ef9a8862b361c68ec12b50582a71711ca96e012","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/1ef9a8862b361c68ec12b50582a71711ca96e012"}],"sha":"1ab909d354f1a27b4403df3b6ed73ce710a2ca57","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/1ab909d354f1a27b4403df3b6ed73ce710a2ca57"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/1ef9a8862b361c68ec12b50582a71711ca96e012/comments","commit":{"author":{"date":"2026-09-27T11:39:15Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T11:39:15Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"chore: version 0.1.0\n\nFirst published version. The package has never been on a registry, so 0.1.0 is\nthe honest starting point; the three features it accumulated (scaffolding, review\ngates, MinIO) all ship in this one release.","tree":{"sha":"d24e63e3f7c90fdba61d9b7b424f73193afa6ad9","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/d24e63e3f7c90fdba61d9b7b424f73193afa6ad9"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/1ef9a8862b361c68ec12b50582a71711ca96e012","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/1ef9a8862b361c68ec12b50582a71711ca96e012","node_id":"C_kwDOUuRmqtoAKDFlZjlhODg2MmIzNjFjNjhlYzEyYjUwNTgyYTcxNzExY2E5NmUwMTI","parents":[{"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e","sha":"8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e"}],"sha":"1ef9a8862b361c68ec12b50582a71711ca96e012","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/1ef9a8862b361c68ec12b50582a71711ca96e012"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e/comments","commit":{"author":{"date":"2026-09-27T11:36:26Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T11:36:26Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"docs: README markdown reformat\n\nWhitespace, table realignment and `*x*` -> `_x_` emphasis, as produced by an\nexternal formatter. Also drops the three npx example lines and the stage numbers\nin the pipeline table; accepted as-is.","tree":{"sha":"52da938e00ee35bce5b25dea2d40a901ebf5aa1f","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/52da938e00ee35bce5b25dea2d40a901ebf5aa1f"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e","node_id":"C_kwDOUuRmqtoAKDhlN2Q2ZDk5NjhlNjM3NzZkMGQwYjY3MTliM2NlMjU5YTQ2ZjBiN2U","parents":[{"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/c35889dfa983bdb7bf2687e0ebfd827600367bb0","sha":"c35889dfa983bdb7bf2687e0ebfd827600367bb0","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/c35889dfa983bdb7bf2687e0ebfd827600367bb0"}],"sha":"8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/8e7d6d9968e63776d0d0b6719b3ce259a46f0b7e"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/c35889dfa983bdb7bf2687e0ebfd827600367bb0/comments","commit":{"author":{"date":"2026-09-27T11:30:07Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T11:30:07Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"chore: mark the bin entry points executable\n\nAll three scripts carry a `#!/usr/bin/env node` shebang but were committed\nwithout the exec bit, so `./bin/install.js` failed on a fresh clone while\n`node bin/install.js` worked. npm sets the bit at install time either way, so\nthis only ever mattered for someone running them straight out of a checkout.","tree":{"sha":"352da4ecf7b916a62c7d449d6e0c391330522fc8","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/352da4ecf7b916a62c7d449d6e0c391330522fc8"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/c35889dfa983bdb7bf2687e0ebfd827600367bb0","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/c35889dfa983bdb7bf2687e0ebfd827600367bb0","node_id":"C_kwDOUuRmqtoAKGMzNTg4OWRmYTk4M2JkYjdiZjI2ODdlMGViZmQ4Mjc2MDAzNjdiYjA","parents":[{"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/db1d396449d9a5744c4162891f0724081efb8b5b","sha":"db1d396449d9a5744c4162891f0724081efb8b5b","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/db1d396449d9a5744c4162891f0724081efb8b5b"}],"sha":"c35889dfa983bdb7bf2687e0ebfd827600367bb0","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/c35889dfa983bdb7bf2687e0ebfd827600367bb0"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/db1d396449d9a5744c4162891f0724081efb8b5b/comments","commit":{"author":{"date":"2026-09-27T11:14:29Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T11:14:29Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"feat: human review gates — 1/2/3 before every install stage\n\nEvery stage of an install is now announced before it happens, and a person\nchooses how much of it to make. The installer prints what the stage will\nwrite — real paths, real counts — and then asks:\n\n    1 = Recommended   2 = Economy       3 = Full\n\nThe rule that keeps it honest: **a level never shrinks the governance tree.**\nAll 33 documents are written at every level. A missing document is not a\nlighter install; it is a hole an agent reads as a fact. A level changes what\nis scaffolded and how much is reported, never what the rules say.\n\nlib/review.js\n  - LEVELS, the 8 gated stages, and createReview({flags, prompter,\n    interactive, quiet}) with gate() / summary()\n  - each decision records its source: asked, assumed, --level, --no-review,\n    --quiet, or \"not applicable\" — so a later run, or a reviewer, can tell an\n    approval from a default that stood in for one\n  - a terminal that closed before anyone answered is `assumed`, not `asked`;\n    that difference is the reason the field exists\n  - a stage with nothing to do says why and does not ask\n\nPer-stage scope (37 / 40 / 44 files for a one-sub-module module pair)\n  - detection, plan, result: verbosity only\n  - intake: economy derives everything and asks nothing; full confirms every\n    detected identity value and prints which values were read rather than typed\n  - governance: the same 33 documents at every level, reported differently\n  - scaffold: economy drops src/test/** and .editorconfig; full adds a CI\n    workflow and a CHANGELOG per repository, pinned plugin versions, and the\n    inventory table in each README\n  - README: economy writes no table, full adds the workspace inventory\n  - MinIO: economy does not look; full proves the bucket with a write and a\n    delete instead of reporting \"created\"\n\nA dropped file drops the sentence that mentions it. The economy pom.xml has no\ntest dependency, no test source directory and no test include, and its README\ndoes not claim `mvn verify` runs anything — a build description is a claim about\ncode, and a level that left the claim behind would have been a lie with a prompt\nin front of it.\n\nFlags\n  - --level=economy|recommended|full answers every gate and does not ask again\n  - --no-review does not ask and does not print the gates\n  - a non-interactive run uses --level, else Recommended, and says so; an\n    unrecognised --level is reported, not silently replaced\n\nFixed along the way\n  - the review was built without a prompter, so no gate could ever ask and every\n    interactive run installed at Recommended with the question never printed\n  - a readline question left pending when stdin closed: Node exited 0 for an\n    install that stopped a third of the way through\n  - bin/check.js declared rowsForCheck twice; hoisting made the self-check''s\n    version win at every call site, so check compared every README block against\n    rows built for a different directory and reported drift the installer had\n    just avoided. npm test now fails on a duplicate function name\n  - the summary counted only documents, so a whole scaffolded repository read\n    as \"nothing else was written\"\n\nAGENTS.md §2.1 now states what a sign-off is: the person has seen the artefact,\nanswered what breaks if it is wrong, and said yes somewhere findable. The agent\nthat produced the work may not sign it off.\n\nnpm test: 13 self-checks, including that every stage the installer announces has\na gate and every gate titles a real stage, that 37/40/44 holds, that the intake\ngrows only at Full, and that this README''s numbers are the plan''s numbers.","tree":{"sha":"68944fff82b19f51bafea4a056a52275a2bd6d7a","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/68944fff82b19f51bafea4a056a52275a2bd6d7a"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/db1d396449d9a5744c4162891f0724081efb8b5b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/db1d396449d9a5744c4162891f0724081efb8b5b","node_id":"C_kwDOUuRmqtoAKGRiMWQzOTY0NDlkOWE1NzQ0YzQxNjI4OTFmMDcyNDA4MWVmYjhiNWI","parents":[{"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/5467231afaa728bfa7a2cedd2a3a53049b6790d4","sha":"5467231afaa728bfa7a2cedd2a3a53049b6790d4","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/5467231afaa728bfa7a2cedd2a3a53049b6790d4"}],"sha":"db1d396449d9a5744c4162891f0724081efb8b5b","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/db1d396449d9a5744c4162891f0724081efb8b5b"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/5467231afaa728bfa7a2cedd2a3a53049b6790d4/comments","commit":{"author":{"date":"2026-09-27T10:31:54Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T10:31:54Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"feat: module scaffolding, README tables, MinIO, anti-slop governance\n\nThe package grows from a governance-document generator into the thing that\ncreates a new module end to end.\n\nScaffolding\n  - new `module-pair` kind with `--parts=both|frontend|backend|docs`\n    (default `both` for module-pair, `docs` otherwise), producing `<slug>_fe`\n    and `<slug>_be` as siblings — 41 files from templates/scaffold/**\n  - the frontend is a Vue 3 Module Federation remote (exposes, router, metadata,\n    preview entry, Prettier + ESLint, its own .env); the backend is Spring Boot 3\n    on Java 21: controller → service → DocumentStorage port → MinioStorageService\n    adapter, @RestControllerAdvice, .env through an EnvironmentPostProcessor, and\n    spotless → checkstyle → tests → spotbugs\n  - scaffolded files carry sha256 in .docs/install.json, so uninstall deletes\n    only what is still byte-for-byte ours\n\nREADME tables\n  - `<!-- routes:start -->` in the frontend README, `<!-- api:start -->` in the\n    backend one, read from vue.config.js exposes / the router and from the Spring\n    @*Mapping annotations; content outside the markers is never touched, and\n    rows that came from the governance tree rather than from code say so\n\nObject storage\n  - `--minio=auto|install|check|skip`: detect locally, ask before installing,\n    and in a non-interactive run print the commands instead of acting. One\n    bucket per module, named after the slug, created with a signed PUT\n\nGovernance\n  - 30 → 33 documents: ANTI-SLOP (02), FORMAT-LINT (05), and a new 09-backend\n    section with SPRING-BOOT and STORAGE\n\nVerification\n  - `check` gains README-table, upload/storage and module-environment checks\n  - `--self` expands a whole scaffold and reads the result back through\n    detectApis/detectRoutes, because a table generated from annotations that\n    cannot be parsed is wrong on its first run\n\nFixes\n  - re-installs carry the recorded identity forward instead of re-deriving it,\n    so a second run cannot create `module_fe` beside `module_demo_fe`\n  - templates that npm or git refuse to ship (.gitignore, .env) are renamed and\n    mapped in PATH_RENAMES, with a self-check assertion; a published install\n    would otherwise have scaffolded repositories without either\n  - detectRoutes resolves relative view paths against the router and skips\n    redirect-only entries; route prefixes are read from `routePrefix =` as well\n    as `routePrefix:`","tree":{"sha":"ac3ce27834468e4c5fe145bdc297638b1c13c015","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/ac3ce27834468e4c5fe145bdc297638b1c13c015"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/5467231afaa728bfa7a2cedd2a3a53049b6790d4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/5467231afaa728bfa7a2cedd2a3a53049b6790d4","node_id":"C_kwDOUuRmqtoAKDU0NjcyMzFhZmFhNzI4YmZhN2EyY2VkZDJhM2E1MzA0OWI2NzkwZDQ","parents":[{"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/c7d6c6942634f16be48b320dcb34d6a57fb854cd","sha":"c7d6c6942634f16be48b320dcb34d6a57fb854cd","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/c7d6c6942634f16be48b320dcb34d6a57fb854cd"}],"sha":"5467231afaa728bfa7a2cedd2a3a53049b6790d4","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/5467231afaa728bfa7a2cedd2a3a53049b6790d4"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/c7d6c6942634f16be48b320dcb34d6a57fb854cd/comments","commit":{"author":{"date":"2026-09-27T08:57:29Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"comment_count":0,"committer":{"date":"2026-09-27T08:57:29Z","email":"luqmanhafiz247@gmail.com","name":"lqmnwido"},"message":"feat: @lqmnwido/dreams-ai-skills — per-repo AI governance generator\n\nGenerates AGENTS.md plus a 30-document .docs/project-governance/** tree\ninto any D-ReAMS repository (Shell, frontend module, shared UI, API).\n\n- Installer (bin/install.js): new-vs-existing detection, Flow A (scope,\n  kind, module name, sub-modules, use case) and Flow B (prefill identity\n  from the code, ask only what code cannot say), every question available\n  as a CLI flag, idempotent, --dry-run, --force with numbered backups.\n- Edit detection uses sha256 hashes recorded in .docs/install.json, not\n  template comparison, so hand-edited files are preserved on uninstall and\n  re-install.\n- Unresolved {{TOKEN}} placeholders stay visible and are reported once at\n  the end; convention tokens are filtered from the report and never guessed.\n- 30 governance documents across 8 sections plus the generated AGENTS.md\n  router, following the 11-step pipeline.\n- check.js validates the tree, the router, identity drift and placeholders;\n  --self runs the package test suite.","tree":{"sha":"3b25ad6ee297d6fbeb3d20e2ff959a4a8346ad40","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/trees/3b25ad6ee297d6fbeb3d20e2ff959a4a8346ad40"},"url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/git/commits/c7d6c6942634f16be48b320dcb34d6a57fb854cd","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47884472?v=4","events_url":"https://api.github.com/users/lqmnwido/events{/privacy}","followers_url":"https://api.github.com/users/lqmnwido/followers","following_url":"https://api.github.com/users/lqmnwido/following{/other_user}","gists_url":"https://api.github.com/users/lqmnwido/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lqmnwido","id":47884472,"login":"lqmnwido","node_id":"MDQ6VXNlcjQ3ODg0NDcy","organizations_url":"https://api.github.com/users/lqmnwido/orgs","received_events_url":"https://api.github.com/users/lqmnwido/received_events","repos_url":"https://api.github.com/users/lqmnwido/repos","site_admin":false,"starred_url":"https://api.github.com/users/lqmnwido/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lqmnwido/subscriptions","type":"User","url":"https://api.github.com/users/lqmnwido","user_view_type":"public"},"html_url":"https://github.com/lqmnwido/dreams-ai-skills/commit/c7d6c6942634f16be48b320dcb34d6a57fb854cd","node_id":"C_kwDOUuRmqtoAKGM3ZDZjNjk0MjYzNGYxNmJlNDhiMzIwZGNiMzRkNmE1N2ZiODU0Y2Q","parents":[],"sha":"c7d6c6942634f16be48b320dcb34d6a57fb854cd","url":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits/c7d6c6942634f16be48b320dcb34d6a57fb854cd"}],"requestUrl":"https://api.github.com/repos/lqmnwido/dreams-ai-skills/commits?per_page=100&page=1&sha=1ab909d354f1a27b4403df3b6ed73ce710a2ca57&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A02%3A36.094Z"}');
