reddym","providerType":"User"},"email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"authoredDate":"2026-09-12T18:36:28Z","committedDate":"2026-09-12T18:36:28Z","committer":{"account":{"login":"sujithareddym","providerType":"User"},"email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"observedAt":"2026-10-09T00:50:57.239Z","repositoryId":1391561940,"sha":"d9f0fadfe6f29400aa4f4beb05393d1100a337c5"},{"author":{"account":{"login":"sujithareddym","providerType":"User"},"email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"authoredDate":"2026-09-12T18:23:12Z","committedDate":"2026-09-12T18:23:12Z","committer":{"account":{"login":"sujithareddym","providerType":"User"},"email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"observedAt":"2026-10-09T00:50:57.239Z","repositoryId":1391561940,"sha":"f45632ca9c6187da85bbf0bcccc4cc2e56558f77"}],"observedAt":"2026-10-09T00:50:57.239Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/6a2b22eb0c2fce85c55fe4804d76c3cd31db6cd4/comments","commit":{"author":{"date":"2026-09-14T00:14:34Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-14T00:14:34Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Make sidebar steps clickable to review/edit; add isMarried checkbox\n\nSidebarSteps now takes an onStepClick prop -- completed (and the\ncurrent) step render as buttons; clicking one shows that step''s\ncontent via a new local \"viewing\" state in QuoteClient, without\ntouching the quote''s real funnelStage. rc1 (\"Your Quote\") already\nrenders the same editable ConfigDrivenPage as schema, so clicking back\ninto it doubles as an edit view for free; \"Update quote\" re-submits\nthe page (safe at any stage -- applyAnswerPatch doesn''t require being\nat ''schema'') and returns to the live step on success, or \"Back to\ncurrent step\" just cancels. Locked entirely once bind starts.\n\nFixed a real bug this surfaced in testing: re-submitting the page\nafter the quote had already reached rc2 recomputed the rate from\nanswers only, silently dropping the MVR violation surcharge (price\nregressed $700 -> $550 while the violation stayed listed). \"Update\nquote\" now re-pulls the report too whenever the live stage is rc2.\n\nSeparately: added a real ''checkbox'' field type end-to-end (CheckboxField,\nregistered in field-registry.ts) for the new isMarried field\nquoteflow-rating-service now ships -- boolean fields store ''true''/\n''false'' the same way every other field type''s value is a string. Wired\ninto both the GaQ form (native checkbox, Radix''s bubble-input form\nparticipation) and ConfigDrivenPage.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"4acd9dd95694c80faf8f47843cf67ed42857b7db","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/4acd9dd95694c80faf8f47843cf67ed42857b7db"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/6a2b22eb0c2fce85c55fe4804d76c3cd31db6cd4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/6a2b22eb0c2fce85c55fe4804d76c3cd31db6cd4","node_id":"C_kwDOUvGM1NoAKDZhMmIyMmViMGMyZmNlODVjNTVmZTQ4MDRkNzZjM2NkMzFkYjZjZDQ","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/bd5ae9550be30fb0238c0a978ce28f49db87974b","sha":"bd5ae9550be30fb0238c0a978ce28f49db87974b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/bd5ae9550be30fb0238c0a978ce28f49db87974b"}],"sha":"6a2b22eb0c2fce85c55fe4804d76c3cd31db6cd4","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/6a2b22eb0c2fce85c55fe4804d76c3cd31db6cd4"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/bd5ae9550be30fb0238c0a978ce28f49db87974b/comments","commit":{"author":{"date":"2026-09-13T23:09:56Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T23:09:56Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Mask and format the SSN field; show distinct content per funnel stage\n\nSsnInput (libs/ui-components, backed by react-imask) formats digits\ninto XXX-XX-XXXX as they''re typed and displays as a password field\n(dots) whenever it''s blurred with a value present, revealing again on\nfocus -- the same \"hide PII at rest, show while editing\" pattern\nbanking/benefits portals use. Wired into both the GaQ form''s plain SSN\ninput and ConfigDrivenPage''s TextField (for any carrier''s ssn-validated\nfield), plus a masked read-only rendering in QuoteClient''s new answer\nsummary below.\n\nSeparately: the \"Your Quote\" (rc1) and \"Driving Record\" (rc2) steps\nwere rendering the exact same editable driver-info form, since Acme''s\nschema has only one page and nothing distinguished the stages beyond\nthe sidebar label. rc1 now shows a read-only recap of what was\nsubmitted; rc2 shows the actual MVR results (violations or a\nclean-record message) via a new `report` field threaded through\nquote-session.store.ts and useQuoteSession''s pullReport -- previously\ndiscarded even though quoteflow-rating-service''s PullReportResponse\nalready returned it.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"c94c20a5659ad51a75f607fb64e49c0929affee6","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/c94c20a5659ad51a75f607fb64e49c0929affee6"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/bd5ae9550be30fb0238c0a978ce28f49db87974b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/bd5ae9550be30fb0238c0a978ce28f49db87974b","node_id":"C_kwDOUvGM1NoAKGJkNWFlOTU1MGJlMzBmYjAyMzhjMGE5NzhjZTI4ZjQ5ZGI4Nzk3NGI","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/441c2ae68eb50d0a98111936f281bb48c6203464","sha":"441c2ae68eb50d0a98111936f281bb48c6203464","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/441c2ae68eb50d0a98111936f281bb48c6203464"}],"sha":"bd5ae9550be30fb0238c0a978ce28f49db87974b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/bd5ae9550be30fb0238c0a978ce28f49db87974b"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/441c2ae68eb50d0a98111936f281bb48c6203464/comments","commit":{"author":{"date":"2026-09-13T22:29:17Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T22:29:17Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Add an applicant-details page to the mock Acme carrier portal\n\nThe Playwright-driven bind now goes through three real pages instead\nof one -- login, an applicant-details form (first/last name, DOB), then\nthe existing bind form -- gated on each other via a real per-session\nMap (previously just a boolean cookie, since there was nothing to\nremember). The applicant-details page needs real driver-info answers,\nnot just a quoteId, so bind-job-handler.ts fetches them from Repo 1''s\nnew internal endpoint (rating-service-quote-lookup.ts) before handing\noff to the Playwright automation -- only for Acme''s path, since\nVantage''s direct API call never needed applicant data.\n\nVerified live: headed Playwright run showed the browser typing real\nGaQ-entered applicant details into the new page before completing the\nbind, and a direct curl to GET /internal/quotes/:quoteId confirmed the\nsame data the portal displayed.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"68ff13be0ef111c4136d35bde6fd555606b5ec68","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/68ff13be0ef111c4136d35bde6fd555606b5ec68"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/441c2ae68eb50d0a98111936f281bb48c6203464","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/441c2ae68eb50d0a98111936f281bb48c6203464","node_id":"C_kwDOUvGM1NoAKDQ0MWMyYWU2OGViNTBkMGE5ODExMTkzNmYyODFiYjQ4YzYyMDM0NjQ","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/4139662714696ac8af68f2a02d8d863b7506dcba","sha":"4139662714696ac8af68f2a02d8d863b7506dcba","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/4139662714696ac8af68f2a02d8d863b7506dcba"}],"sha":"441c2ae68eb50d0a98111936f281bb48c6203464","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/441c2ae68eb50d0a98111936f281bb48c6203464"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/4139662714696ac8af68f2a02d8d863b7506dcba/comments","commit":{"author":{"date":"2026-09-13T22:27:00Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T22:27:00Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Fix: include files dropped from the GaQ compare-page commit\n\nThe previous commit (62eca0d) was supposed to include these 8 files\nbut a lint-staged/husky stash step silently left them out -- git\nstatus here still showed them as uncommitted changes against a stale\nHEAD, even though the working tree (and everything verified live) had\nbeen correct all along. Most notably this was missing the actual fix\nto useQuoteSession.ts''s fromSchemaResponse (rate: data.rate instead of\na hardcoded null) and the new thin Server Component quote/page.tsx\nthat QuoteClient.tsx depends on -- a fresh clone of the prior commit\nwould not have had a working GaQ/resume flow despite the commit\nmessage claiming otherwise.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"e5e3ecc1a872544165943f4519964a134514ebe4","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/e5e3ecc1a872544165943f4519964a134514ebe4"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/4139662714696ac8af68f2a02d8d863b7506dcba","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/4139662714696ac8af68f2a02d8d863b7506dcba","node_id":"C_kwDOUvGM1NoAKDQxMzk2NjI3MTQ2OTZhYzhhZjY4ZjJhMDJkOGQ4NjNiNzUwNmRjYmE","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/62eca0d90e459a96cfb4d5518d38a504d8537644","sha":"62eca0d90e459a96cfb4d5518d38a504d8537644","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/62eca0d90e459a96cfb4d5518d38a504d8537644"}],"sha":"4139662714696ac8af68f2a02d8d863b7506dcba","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/4139662714696ac8af68f2a02d8d863b7506dcba"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/62eca0d90e459a96cfb4d5518d38a504d8537644/comments","commit":{"author":{"date":"2026-09-13T19:52:04Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T19:52:04Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Add GaQ compare page: rate both carriers, then continue into PaP\n\nGet a Quote is now a server-rendered form (/quote/start, a Next.js\nServer Action, no client session store) that rates Acme and Vantage\nfrom one submission and redirects to /quote/compare, a server-rendered\nside-by-side price comparison. Choosing a carrier links into the\nexisting PaP flow at /quote?resume=<quoteId> — useQuoteSession''s\nresumeQuoteId hydration already wrote resumed quotes to sessionStorage,\nso PaP itself (rc1 to rc2 to bind, config-driven) needed no changes,\njust a guard so it doesn''t auto-start a fresh Acme quote on resume.\n\nSplit /quote/page.tsx into a thin Server Component (awaits\nsearchParams) plus QuoteClient.tsx (plain resumeQuoteId prop) rather\nthan reading the searchParams Promise via use() in the client\ncomponent, which suspends with no Suspense boundary in this app''s\ntests. Also fixed fromSchemaResponse in useQuoteSession.ts, which\nwas hardcoding rate: null instead of reading the schema response''s\nnow-present rate field -- a resumed quote would otherwise have shown\nno price until the user re-submitted a page.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"b41a1ca7a1b16c164ae06d7a99850a4ed2fcedff","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/b41a1ca7a1b16c164ae06d7a99850a4ed2fcedff"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/62eca0d90e459a96cfb4d5518d38a504d8537644","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/62eca0d90e459a96cfb4d5518d38a504d8537644","node_id":"C_kwDOUvGM1NoAKDYyZWNhMGQ5MGU0NTlhOTZjZmI0ZDU1MThkMzhhNTA0ZDg1Mzc2NDQ","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b","sha":"40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b"}],"sha":"62eca0d90e459a96cfb4d5518d38a504d8537644","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/62eca0d90e459a96cfb4d5518d38a504d8537644"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b/comments","commit":{"author":{"date":"2026-09-13T18:40:57Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T18:40:57Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Document Vantage Direct''s API-driven bind alongside Acme''s Playwright path\n\nUpdates the architecture diagram, apps table, setup steps, and the\nRabbitMQ hand-off walkthrough in README.md, plus CLAUDE.md''s\nautomation-worker entry, to reflect bind-job-handler.ts''s\nAPI_DRIVEN_CARRIER_CODES split: Acme -> Playwright against a mock\nportal, Vantage Direct -> a direct fetch() call to a mock REST API,\npicked per job by carrierCode, converging on the same result shape so\nnothing downstream needs to know which one ran.\n\nAlso calls out honestly, in a Scope note, that customer-portal and\nagent-portal still hardcode carrierCode: ''acme'' — Vantage''s quote/bind\nlifecycle is real and verified live via direct API calls, just not yet\nreachable by clicking through either portal.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"541f0e4f8a7e81c97826a6aa89fbe71dd945489e","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/541f0e4f8a7e81c97826a6aa89fbe71dd945489e"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b","node_id":"C_kwDOUvGM1NoAKDQwZjY2ZmM5ZDhkZGM3YjRhZDAyN2QxNDE0Y2ZhMDBiMDRiOGRmNWI","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/2075a33aa040bfeec501090f036c4ce16c1d23b0","sha":"2075a33aa040bfeec501090f036c4ce16c1d23b0","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/2075a33aa040bfeec501090f036c4ce16c1d23b0"}],"sha":"40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/40f66fc9d8ddc7b4ad027d1414cfa00b04b8df5b"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/2075a33aa040bfeec501090f036c4ce16c1d23b0/comments","commit":{"author":{"date":"2026-09-13T18:37:28Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T18:37:28Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Add API-driven bind for Vantage Direct alongside Acme''s Playwright path\n\nAcme''s carrier-bind-automation.ts (Playwright against a mock HTML\nportal) is untouched. Vantage Direct — the new carrier just added on the\nquoteflow-rating-service side — binds through a completely different\nmechanism: a mock carrier REST API (src/mock-carrier-api, bare Express +\nJSON, bearer-token auth instead of a session-cookie login) and a plain\nfetch()-based client (carrier-api-automation.ts) instead of a browser.\n\nbind-job-handler.ts picks which one runs off the job''s own carrierCode\n(API_DRIVEN_CARRIER_CODES) — everything else about job handling (retry\nreporting, the DLQ decision, error propagation) is identical regardless\nof which mechanism ran. Both automate() and callCarrierApi() are\ninjectable deps, matching the existing test pattern.\n\n`npm run dev` now starts three processes (portal, api, worker) instead\nof two; the Nx build target''s additionalEntryPoints picks up the new\nmock-carrier-api/server.ts.\n\nVerified live against the real broker: a Vantage quote bound via the API\npath (policyNumber VNTG-...) with zero browser involvement, and an Acme\nquote in the same running worker still bound via Playwright\n(policyNumber ACME-...) — including hitting and recovering from the mock\nportal''s own random failure rate on the very same run, proving the two\npaths are genuinely independent, not a shared code path with a flag.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"94d3099d23c6301ffcf802fd9c3bb7cd45053107","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/94d3099d23c6301ffcf802fd9c3bb7cd45053107"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/2075a33aa040bfeec501090f036c4ce16c1d23b0","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/2075a33aa040bfeec501090f036c4ce16c1d23b0","node_id":"C_kwDOUvGM1NoAKDIwNzVhMzNhYTA0MGJmZWVjNTAxMDkwZjAzNmM0Y2UxNmMxZDIzYjA","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/e7e554accf424264659140af0ad2f54385dd4e71","sha":"e7e554accf424264659140af0ad2f54385dd4e71","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/e7e554accf424264659140af0ad2f54385dd4e71"}],"sha":"2075a33aa040bfeec501090f036c4ce16c1d23b0","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/2075a33aa040bfeec501090f036c4ce16c1d23b0"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/e7e554accf424264659140af0ad2f54385dd4e71/comments","commit":{"author":{"date":"2026-09-13T04:20:33Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T04:20:33Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 12: top-level README + CLAUDE.md with the real architecture\n\nReplaces the raw Nx-scaffold README with an actual architecture writeup\nmatching quoteflow-rating-service''s own README bar: what each app/lib\ndoes, a diagram spanning both repos (customer-portal/agent-portal ->\nbff-gateway -> quoteflow-rating-service, the assistant''s separate\npgvector store, and the RabbitMQ hand-off to automation-worker), setup\ninstructions, and the DLQ CLI.\n\nExtends CLAUDE.md (kept the Nx-managed block intact, added a new section\nabove it) with the two rules everything else in this repo depends on —\nbff-gateway proxies quote data rather than owning it, and the\nassistant''s Postgres is a separate database from Repo 1''s — plus a\nper-directory map and the conventions (module-loader''s Function()\ndynamic-import indirection, Zustand over useState for hooks that read\ntheir own latest state from inside an async function, .js-extension\nimports in libs but not in the Next.js apps) that aren''t obvious from\nreading any single file.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"b8537cf8a4d51ced8a5a1c41bc116b3683f11230","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/b8537cf8a4d51ced8a5a1c41bc116b3683f11230"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/e7e554accf424264659140af0ad2f54385dd4e71","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/e7e554accf424264659140af0ad2f54385dd4e71","node_id":"C_kwDOUvGM1NoAKGU3ZTU1NGFjY2Y0MjQyNjQ2NTkxNDBhZjBhZDJmNTQzODVkZDRlNzE","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/1d74fa02c0ed95267afd615a805a463aa3bdc056","sha":"1d74fa02c0ed95267afd615a805a463aa3bdc056","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/1d74fa02c0ed95267afd615a805a463aa3bdc056"}],"sha":"e7e554accf424264659140af0ad2f54385dd4e71","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/e7e554accf424264659140af0ad2f54385dd4e71"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/1d74fa02c0ed95267afd615a805a463aa3bdc056/comments","commit":{"author":{"date":"2026-09-13T04:14:43Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T04:14:43Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 11: OpenTelemetry in bff-gateway + ADR-0002\n\nMirrors quoteflow-rating-service''s own telemetry/otel.ts setup exactly\n(same file path, same console-exporter default, same auto-\ninstrumentations-node package) so a trace crossing the bff-gateway ->\nrating-service boundary is one inspectable trace once both point at the\nsame collector — verified live: a POST /quotes hitting bff-gateway and\nits outbound proxy call to rating-service share the same traceId.\n\ndocs/adr/0002 documents this as a (fictional, for narrative purposes)\nmigration off a legacy in-house APM agent, mirroring quoteflow-rating-\nservice''s own ADR-0001 format — a deliberate docs-vs-code detail: the\ncodebase never had a legacy agent, but the ADR is written the way a real\nmigration record would be, including what was given up (a PII-redaction\nconvenience the old agent had that OpenTelemetry doesn''t replicate\nout of the box).\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"46aa4e1e6eeec810d0c1cafe1360a927c9e0c225","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/46aa4e1e6eeec810d0c1cafe1360a927c9e0c225"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/1d74fa02c0ed95267afd615a805a463aa3bdc056","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/1d74fa02c0ed95267afd615a805a463aa3bdc056","node_id":"C_kwDOUvGM1NoAKDFkNzRmYTAyYzBlZDk1MjY3YWZkNjE1YTgwNWE0NjNhYTNiZGMwNTY","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4","sha":"8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4"}],"sha":"1d74fa02c0ed95267afd615a805a463aa3bdc056","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/1d74fa02c0ed95267afd615a805a463aa3bdc056"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4/comments","commit":{"author":{"date":"2026-09-13T04:02:47Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T04:02:47Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 10: libs/ai-assistant — RAG over pgvector + Gemini tool calling\n\nThe assistant answers coverage questions grounded in a real knowledge\nbase instead of pure model knowledge, and can look up the customer''s\nown quote instead of only working from whatever''s in the chat so far:\n\n- libs/ai-assistant (Node-only, mirrors feature-flags''s shape): a Gemini\n  client wrapper (chat streaming + embeddings), a pgvector-backed\n  knowledge store (cosine similarity via `<=>`, embeddings stored as\n  `vector(768)`), a chat-service orchestrator that embeds the user''s\n  latest message, retrieves top-k coverage docs, streams Gemini''s\n  response, and — if Gemini calls the one wired-up tool\n  (get_quote_summary) — runs it and streams a grounded follow-up.\n- A second, dedicated Postgres (pgvector extension) on :5433 for the\n  assistant''s knowledge base — separate from quoteflow-rating-service''s\n  own database, so bff-gateway''s \"no direct quote-data database\"\n  architecture still holds (this is assistant knowledge, not quote data).\n  Seeded via `npm run seed:assistant` with six static coverage-explainer\n  docs (deductibles, SR-22, liability, etc.).\n- bff-gateway''s new POST /assistant/chat (SSE, one ChatStreamEvent per\n  line) and POST /assistant/feedback, wired to Gemini + the pgvector\n  store + a get_quote_summary executor backed by RatingServiceClientService.\n- Frontend: ChatMessageBubble (ui-components), a Zustand-backed\n  useChatStream() (libs/state, same pattern as useQuoteSession — see\n  below for why), and customer-portal''s floating AssistantChatWidget\n  wiring them together with the already-existing ChatPanelShell/\n  FeedbackButtons.\n\nTwo real bugs found only by testing against the live Gemini API (never\nwould have shown up mocked):\n- Newer Gemini models attach a `thoughtSignature` to function-call\n  response parts; echoing the model''s turn back on the follow-up request\n  without it is rejected (\"Function call is missing a thought_signature\").\n  Fixed by capturing the whole response Part (not just the FunctionCall\n  payload) and replaying it verbatim.\n- `text-embedding-004` isn''t available on this API key/version; switched\n  the default embedding model to `gemini-embedding-001` after querying\n  ai.models.list() for what actually supports embedContent.\n\nAlso: a useState-based useChatStream lost state intermittently under\nrenderHook + act() in this React 19 + testing-library setup (internal\ndebug logging proved the state updates themselves were correct — this\nwas a test-environment artifact, not a logic bug). Rewrote it as a\nZustand store exactly like quote-session.store.ts, which sidesteps the\nissue entirely and matches this codebase''s existing pattern for hooks\nthat need to read the latest state from inside a long-running async\nfunction.\n\nVerified live end-to-end: RAG-grounded answers with accurate citations,\na full get_quote_summary tool-call round trip returning real quote data,\nthumbs-up feedback persisted to chat_feedback, and the chat widget\nworking in the browser on customer-portal''s /quote page.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"fd9eaa6099b6a419416bc92cdb4bc434473b6669","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/fd9eaa6099b6a419416bc92cdb4bc434473b6669"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4","node_id":"C_kwDOUvGM1NoAKDhiZDc3MDkyOThjNDgyNGVlMmZkNDE5ZjhjMmNmNGRlZGM4Y2JiYTQ","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/027932b79f4178a3d5092b6cebc33ea4871972f6","sha":"027932b79f4178a3d5092b6cebc33ea4871972f6","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/027932b79f4178a3d5092b6cebc33ea4871972f6"}],"sha":"8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/8bd7709298c4824ee2fd419f8c2cf4dedc8cbba4"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/027932b79f4178a3d5092b6cebc33ea4871972f6/comments","commit":{"author":{"date":"2026-09-13T01:49:00Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T01:49:00Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 9: apps/automation-worker (RabbitMQ consumer + mock carrier portal + DLQ CLI)\n\nConsumes carrier.bind.requested, drives a bare Express + server-rendered\nHTML \"Acme carrier portal\" (deliberately not a React SPA) via Playwright —\nlog in, fill the bind form, submit, scrape #result/#error — and reports\nprogress back to quoteflow-rating-service''s internal callback route.\nApplies the retry/DLQ pattern from this project''s playx reference: a\ncustom x-retry-count header (not RabbitMQ''s x-death, so the count\nsurvives the ack+republish retry style), nack-without-requeue once\nretries are exhausted so the main queue''s own x-dead-letter-exchange\nargument routes to the DLQ, and a `dlq` CLI (depth/list/replay/purge) to\ninspect and recover from it.\n\nTwo things this diverged from playx on, both found by testing against\nthe real broker rather than assuming the pattern would just work:\n\n- No retry backoff in the naive port of the pattern meant a transient\n  failure burned all its retries in the same instant (observed: rating-\n  service still booting caused 4 attempts inside ~50ms, landing a\n  perfectly recoverable job straight in the DLQ). Added exponential\n  backoff (1s/2s/4s, capped at 10s) before each republish; prefetch(1)\n  means this only throttles retries of the same job, never blocks others.\n- The DLQ `list`/peek command nacked-with-requeue one message at a time,\n  which on a queue with just 1 message put it right back at the front\n  for the very next get() — printing the same message N times instead of\n  stopping. Fixed by snapshotting the queue depth first and only\n  requeuing everything at the end, once all distinct messages are in hand.\n\nVerified live end-to-end against the real broker: happy path (bind ->\nPlaywright -> mock portal -> succeeded), a forced worker-side failure\nretried with visible backoff, exhausted-retries routing to the DLQ,\n`dlq list` showing it without removing it, and `dlq replay` putting it\nback on the main queue where it then succeeded.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"9f776b6be2d0bd8cb9c62085bd05b3f7797ad981","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/9f776b6be2d0bd8cb9c62085bd05b3f7797ad981"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/027932b79f4178a3d5092b6cebc33ea4871972f6","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/027932b79f4178a3d5092b6cebc33ea4871972f6","node_id":"C_kwDOUvGM1NoAKDAyNzkzMmI3OWY0MTc4YTNkNTA5MmI2Y2ViYzMzZWE0ODcxOTcyZjY","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/510db909bbb994583ef89296b559edda947e93bc","sha":"510db909bbb994583ef89296b559edda947e93bc","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/510db909bbb994583ef89296b559edda947e93bc"}],"sha":"027932b79f4178a3d5092b6cebc33ea4871972f6","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/027932b79f4178a3d5092b6cebc33ea4871972f6"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/510db909bbb994583ef89296b559edda947e93bc/comments","commit":{"author":{"date":"2026-09-13T01:14:02Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T01:14:02Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 8: libs/feature-flags + one flagged UI variant\n\nOpenFeature-style flag evaluation: FeatureFlagProvider is the interface a\nreal SDK would implement, FeatureFlagClient is the only thing application\ncode depends on (never a provider directly), and every resolve fails open\nto the caller''s default rather than throwing. Two providers:\n\n- local-file-provider.ts (the default here): reads a flat JSON file once\n  at startup, no network call.\n- launch-darkly-provider.ts: stubbed to the same provider shape a real\n  @launchdarkly/node-server-sdk-backed provider would have, so migrating\n  off the local file is just swapping which provider gets passed to\n  createFeatureFlagClient() — no call site changes.\n\nWired end-to-end through one flag: bff-gateway''s new GET /flags resolves\ncustomer-portal.show-savings-badge from apps/bff-gateway/flags.local.json\nvia a FeatureFlagsService; customer-portal''s landing page (a server\ncomponent) calls it directly at request time and passes the result into\nOptionCard''s existing badge prop — no client fetch, no loading state.\nVerified live by flipping the JSON value and confirming the badge\nappears/disappears on :3000.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"e258a3aea3b6993bf3a3f78e52e0a0a38891b6d1","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/e258a3aea3b6993bf3a3f78e52e0a0a38891b6d1"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/510db909bbb994583ef89296b559edda947e93bc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/510db909bbb994583ef89296b559edda947e93bc","node_id":"C_kwDOUvGM1NoAKDUxMGRiOTA5YmJiOTk0NTgzZWY4OTI5NmI1NTllZGRhOTQ3ZTkzYmM","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b","sha":"d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b"}],"sha":"510db909bbb994583ef89296b559edda947e93bc","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/510db909bbb994583ef89296b559edda947e93bc"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b/comments","commit":{"author":{"date":"2026-09-13T00:53:07Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T00:53:07Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 7: apps/agent-portal reusing the same libs with an agent-only override\n\nSame landing + /quote page structure as customer-portal, same\nuseQuoteSession/ConfigDrivenPage/ui-components libs — the only functional\ndifference is /quote resolving its page config via useCarrierRouteConfig\nwith portal: ''agent'' instead of the customer/no-state baseline off\nsession.schema. That one prop applies quoteflow-rating-service''s\nagent-only override (routeConfigs/overrides.ts hides the phone field for\nthe agent portal): verified live, side-by-side with customer-portal —\nsame code path, phone field present on :3000 and absent on :3001.\n\nRuns on :3001 via an explicit `next dev -p 3001` in project.json, since\nthe inferred dev target defaults to Next''s port 3000 like customer-portal.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"406ddd03db5014d43176d39f460fef08c8bb0789","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/406ddd03db5014d43176d39f460fef08c8bb0789"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b","node_id":"C_kwDOUvGM1NoAKGQ1MGI3YzU1ZTljOWEwYmQ2ZjNlYzI4ODFmMzMwYTM0YzViOGQ0N2I","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/9881e0ce5f625179c6a31eaa060aab54aa88afc5","sha":"9881e0ce5f625179c6a31eaa060aab54aa88afc5","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/9881e0ce5f625179c6a31eaa060aab54aa88afc5"}],"sha":"d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/d50b7c55e9c9a0bd6f3ec2881f330a34c5b8d47b"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/9881e0ce5f625179c6a31eaa060aab54aa88afc5/comments","commit":{"author":{"date":"2026-09-13T00:46:24Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-13T00:46:24Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Prerequisite for milestone 7: portal-aware config resolution in form-renderer\n\nagent-portal needs to resolve its page config with the agent-only override\napplied (e.g. hiding the phone field), not the customer/no-state baseline\nthat GET /quotes/:quoteId/schemas always returns. Adds config-loader.ts\n(fetches the manifest, dynamic-imports the carrier''s compiled config\nbundle, calls its exported resolver with the given portal/state) and the\nuseCarrierRouteConfig hook both portals will share.\n\nFactored the caching dynamic-import machinery validator-loader.ts already\nhad into a generic module-loader.ts so config-loader reuses it instead of\nduplicating the cache-by-URL + injectable-importer logic.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"09be8190633555b69b16090397c3ab2e9a321436","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/09be8190633555b69b16090397c3ab2e9a321436"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/9881e0ce5f625179c6a31eaa060aab54aa88afc5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/9881e0ce5f625179c6a31eaa060aab54aa88afc5","node_id":"C_kwDOUvGM1NoAKDk4ODFlMGNlNWY2MjUxNzljNmEzMWVhYTA2MGFhYjU0YWE4OGFmYzU","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/12500390bc02cadc07fd8ea852e4d2592c0b261d","sha":"12500390bc02cadc07fd8ea852e4d2592c0b261d","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/12500390bc02cadc07fd8ea852e4d2592c0b261d"}],"sha":"9881e0ce5f625179c6a31eaa060aab54aa88afc5","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/9881e0ce5f625179c6a31eaa060aab54aa88afc5"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/12500390bc02cadc07fd8ea852e4d2592c0b261d/comments","commit":{"author":{"date":"2026-09-12T21:20:37Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T21:20:37Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Visual redesign: gradient background, pill CTAs, sidebar step-nav\n\nRequested UI direction similar to a real insurance quote flow\n(Goosehead''s quotes-next app) — same layout language, different\npalette: an indigo/violet brand color instead of green, so this reads\nas QuoteFlow''s own look rather than a copy.\n\n- Design tokens (libs/ui-components/globals.css): new indigo primary\n  color (oklch(0.53 0.21 264) light / oklch(0.68 0.18 264) dark),\n  larger base border radius (1rem), and a `.bg-app-gradient` utility\n  (soft indigo -> cyan two-tone background) for the pre-quote and\n  quote-flow pages.\n- Button is now pill-shaped (rounded-full) for filled/outline/\n  secondary variants, taller (h-10/h-12); Input and Select''s trigger\n  are taller and more rounded (h-11, rounded-xl) — matching the\n  softer, bigger pill-style form controls in the reference.\n- New organism SidebarSteps: a grouped vertical step nav (section\n  heading + steps, current one highlighted with a colored left\n  border + tint) — the sidebar-driven equivalent of StepIndicator for\n  flows worth grouping under section headings.\n- New molecule OptionCard: a big selectable card (icon, title,\n  description, an optional \"Bundle\"-style badge, a checkbox in the\n  corner) — for \"pick one of these\" choices like a product picker.\n- AppShell gained `gradient` and `sidebar` props (sidebar renders\n  beside `children` in a responsive flex row) rather than bolting\n  this onto individual pages.\n- customer-portal wired both in: the landing page shows a\n  pre-selected \"Auto\" OptionCard over the gradient background;\n  the quote page replaced its horizontal StepIndicator with\n  SidebarSteps (grouped into \"Build your plan\" / \"Review & purchase\",\n  matching the reference''s section structure) alongside the\n  gradient-backed AppShell.\n- Verified visually in Storybook (OptionCard''s selection toggle\n  actually works: clicking Home deselects Auto and selects Home) and\n  live in the browser end-to-end: landing page -> quote form (rounded\n  pill inputs, indigo focus rings) -> submitted successfully ($600\n  rate computed) -> sidebar correctly advanced from \"Personal\n  Details\" to \"Your Quote\" as the highlighted current step.\n- All 11 customer-portal tests and the full ui-components suite still\n  pass; a clean `next build` still produces all three routes\n  correctly. Also hit and fixed an unrelated Turbopack cache\n  corruption (stale .next dir from an earlier concurrent build) by\n  clearing apps/customer-portal/.next — not a code issue.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"cb8df508fcf46917c73df6b69485969c0aac221b","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/cb8df508fcf46917c73df6b69485969c0aac221b"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/12500390bc02cadc07fd8ea852e4d2592c0b261d","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/12500390bc02cadc07fd8ea852e4d2592c0b261d","node_id":"C_kwDOUvGM1NoAKDEyNTAwMzkwYmMwMmNhZGMwN2ZkOGVhODUyZTRkMjU5MmMwYjI2MWQ","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/4295f239e2ee52c951beea90667c048896f5d0b2","sha":"4295f239e2ee52c951beea90667c048896f5d0b2","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/4295f239e2ee52c951beea90667c048896f5d0b2"}],"sha":"12500390bc02cadc07fd8ea852e4d2592c0b261d","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/12500390bc02cadc07fd8ea852e4d2592c0b261d"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/4295f239e2ee52c951beea90667c048896f5d0b2/comments","commit":{"author":{"date":"2026-09-12T20:54:40Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T20:54:40Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 6: apps/customer-portal end-to-end against live Repo 1\n\n- Server-rendered landing page (/, no quoteId yet, fast first paint)\n  linking into a client-rendered /quote flow (useQuoteSession +\n  ConfigDrivenPage) — the SSR/CSR boundary the spec calls for.\n- Wired bff-gateway''s new bind/bind-status/bind-events proxy\n  endpoints and useQuoteSession''s requestBind/getBindStatus so the\n  flow actually reaches bind kickoff, with a simple poll loop showing\n  live status once funnelStage is ''bind''.\n- Fixed three real, only-visible-when-actually-built issues:\n  1. ui-components/form-renderer/state each build to ONE bundled\n     dist/index.js; importing any export (even a hook-free one like\n     Button) pulled in the whole module graph, including hook-using\n     code, which Next''s RSC analysis then refused to treat as a\n     Server Component. Fixed by injecting a ''use client'' banner at\n     the Rolldown output level (a source-level directive gets\n     dropped when modules are concatenated).\n  2. The Pattern 2 dynamic import (`import(url)` for a runtime URL)\n     got rejected by every bundler''s static analysis (\"Module not\n     found: Can''t resolve <dynamic>\") even though it''s completely\n     valid at runtime — fixed by hiding it inside `new Function(...)`,\n     the standard portable way to opt a genuinely dynamic import out\n     of static resolution.\n  3. Tailwind v4''s automatic content detection respects .gitignore,\n     so it never saw the class names baked into the (gitignored)\n     dist/ bundles this app imports from — fixed with explicit\n     @source directives pointing at the *source* .tsx files instead.\n  4. A real architectural gap surfaced live: bff-gateway''s\n     server-to-server calls carry no Origin header (Node''s fetch\n     never sends one), which Repo 1''s deliberately-strict CORS policy\n     on /quotes rejects. Fixed by having bff-gateway identify itself\n     with its own Origin header (api-client''s createRatingServiceClient\n     now takes optional defaultHeaders) rather than loosening Repo 1''s\n     policy for everyone; added bff-gateway''s origin to Repo 1''s\n     CORS_ORIGINS allowlist. Also added permissive CORS to Repo 1''s\n     /bundles route specifically, since the browser fetches those\n     directly (not through bff-gateway) via fetch()/dynamic import(),\n     both of which need CORS headers cross-origin.\n- Verified the entire flow live in a real browser against real\n  Postgres/Redis/RabbitMQ: filled the driver-info form, watched the\n  rate go 600 -> 775 across rc1 -> rc2 (MVR violation applied),\n  clicked Purchase, watched funnelStage reach ''bind'', confirmed the\n  carrier.bind.requested message actually landed in RabbitMQ.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"ea601d89476ab5a354a38c35b5fce72e7a3cb792","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/ea601d89476ab5a354a38c35b5fce72e7a3cb792"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/4295f239e2ee52c951beea90667c048896f5d0b2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/4295f239e2ee52c951beea90667c048896f5d0b2","node_id":"C_kwDOUvGM1NoAKDQyOTVmMjM5ZTJlZTUyYzk1MWJlZWE5MDY2N2MwNDg4OTZmNWQwYjI","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/a7e68a96df4f1947cfd66e09a5c9d137f426301e","sha":"a7e68a96df4f1947cfd66e09a5c9d137f426301e","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/a7e68a96df4f1947cfd66e09a5c9d137f426301e"}],"sha":"4295f239e2ee52c951beea90667c048896f5d0b2","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/4295f239e2ee52c951beea90667c048896f5d0b2"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/a7e68a96df4f1947cfd66e09a5c9d137f426301e/comments","commit":{"author":{"date":"2026-09-12T19:49:05Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T19:49:05Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 5: libs/state (Zustand store + useQuoteSession)\n\n- quote-session.store.ts: a plain module-level Zustand store — safe\n  here specifically because everything that touches it is\n  client-rendered only (see the SSR/CSR boundary), so there''s no\n  cross-request leak risk a server-rendered app would have.\n- session-storage.ts: sessionStorage read/write-through, namespaced\n  per quoteId, wrapped in try/catch (a private-browsing quota error\n  must never break typing in the form).\n- useQuoteSession() is the single integration point pages use — they\n  never touch sessionStorage or the API client directly:\n  - setFieldValue writes to the store AND sessionStorage immediately\n    (the durable-vs-immediate split the spec calls for).\n  - submitPage builds JSON Patch ops from the current page''s answers\n    and PATCHes bff-gateway (not quoteflow-rating-service directly —\n    the browser only ever talks to bff-gateway).\n  - On a resume link, sessionStorage is checked first; only on a miss\n    does it hydrate from bff-gateway''s now-answers-including schema\n    endpoint (the Repo 1 fix from the prior commit).\n- Added CarrierRef/BundleRef named types to api-client so the store\n  and hook aren''t inlining the same anonymous object shape repeatedly.\n- 17 tests covering the store''s reducers, sessionStorage''s isolation\n  between quoteIds and corrupted-JSON handling, and the hook''s full\n  read/write-through behavior (create, field edits, page submit\n  including the zero-answers no-op case, upstream-error passthrough,\n  and both resume paths — cache hit and cache miss).\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"5dabe022a9e2c10362f8bd4906d869bbd107b3df","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/5dabe022a9e2c10362f8bd4906d869bbd107b3df"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/a7e68a96df4f1947cfd66e09a5c9d137f426301e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/a7e68a96df4f1947cfd66e09a5c9d137f426301e","node_id":"C_kwDOUvGM1NoAKGE3ZTY4YTk2ZGY0ZjE5NDdjZmQ2NmUwOWE1YzlkMTM3ZjQyNjMwMWU","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/be617853565b2819ebbf414183adb43d66392cef","sha":"be617853565b2819ebbf414183adb43d66392cef","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/be617853565b2819ebbf414183adb43d66392cef"}],"sha":"a7e68a96df4f1947cfd66e09a5c9d137f426301e","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/a7e68a96df4f1947cfd66e09a5c9d137f426301e"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/be617853565b2819ebbf414183adb43d66392cef/comments","commit":{"author":{"date":"2026-09-12T19:31:33Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T19:31:33Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Prerequisite for milestone 5: scaffold apps/bff-gateway (NestJS)\n\nThe spec''s build order has libs/state''s useQuoteSession() write\nthrough to bff-gateway starting at milestone 5, but bff-gateway itself\nis never listed as its own scaffolding step — it has to exist first.\n\n- QuotesModule proxies the quote-lifecycle endpoints useQuoteSession\n  will need (create/schema/patch/reports) to quoteflow-rating-service\n  via api-client''s typed client; bff-gateway has no direct Postgres\n  connection, matching the spec''s HTTP-only boundary.\n- unwrapResult() turns api-client''s Result into either plain data or\n  an HttpException carrying the upstream status/code straight through\n  (falls back to 502 for a network-level failure) — the same\n  Result-so-you-don''t-throw contract from api-client, adapted to\n  Nest''s exception-filter model.\n- env.ts fails fast on a missing RATING_SERVICE_URL, same convention\n  as quoteflow-rating-service. Hit a real Zod v4 API break doing this\n  (required_error was renamed to error) — different repo, different\n  zod major version, so no cross-repo inconsistency, just caught by\n  actually running typecheck instead of assuming v3 syntax.\n- Fixed two bugs in the @nx/nest-generated bff-gateway-e2e app: its\n  jest.config.cts used ESM import/export default syntax, which Node''s\n  CommonJS loader for .cts files rejects outright; and its default\n  port assumption (3000) collided with customer-portal''s planned\n  port, needed updating to bff-gateway''s actual 4100.\n- Verified live, not just unit-tested: booted the real server,\n  confirmed CORS preflight headers for the two frontend origins, and\n  confirmed a call to /quotes 502s with a clear network_error when the\n  rating service isn''t reachable (it isn''t, in this environment —\n  Docker''s been stuck) rather than hanging or crashing. Also ran the\n  e2e suite for real (nx e2e bff-gateway-e2e): it boots the actual\n  app and hits it over HTTP, both tests passing.\n- Added .env/.env.local to .gitignore (missing at the repo root) after\n  noticing apps/bff-gateway/.env was about to be staged.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"421ac1d7a9bd392fed8fe94826a599230924e671","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/421ac1d7a9bd392fed8fe94826a599230924e671"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/be617853565b2819ebbf414183adb43d66392cef","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/be617853565b2819ebbf414183adb43d66392cef","node_id":"C_kwDOUvGM1NoAKGJlNjE3ODUzNTY1YjI4MTllYmJmNDE0MTgzYWRiNDNkNjYzOTJjZWY","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/e85775299dc94247838d34e5be1d9a677232c9ff","sha":"e85775299dc94247838d34e5be1d9a677232c9ff","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/e85775299dc94247838d34e5be1d9a677232c9ff"}],"sha":"be617853565b2819ebbf414183adb43d66392cef","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/be617853565b2819ebbf414183adb43d66392cef"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/e85775299dc94247838d34e5be1d9a677232c9ff/comments","commit":{"author":{"date":"2026-09-12T19:13:24Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T19:13:24Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 4: Pattern 2 wiring — dynamic validator import in the browser\n\n- validator-loader.ts: dynamic-imports a validator bundle by URL and\n  caches the module by that URL (which embeds the content hash, so a\n  rebuilt bundle is a cache miss automatically). The importer is\n  injectable purely for testing the caching logic in Jest — babel''s\n  CJS transform of import() can''t resolve an arbitrary runtime URL\n  the way a real browser does, so production code always takes the\n  real-import default and the loader''s actual dynamic-import behavior\n  gets verified when it''s exercised in a real browser (milestone 6),\n  not faked here.\n- useValidatorRunner(ratingServiceBaseUrl): fetches bundles/\n  manifest.json once (cached per base URL), resolves the validators\n  bundle URL from it, and runs a named validator — every step cached\n  so repeated on-blur calls only pay for the first one.\n- ConfigDrivenPage now actually wires this in: blurring a field with\n  a `validator` name runs it client-side and shows the message;\n  server-reported errors (the `errors` prop) still take precedence\n  over a passing client-side check, tested explicitly.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"048d79cbeec28ca21cdd97e0af8c77b0898c21fb","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/048d79cbeec28ca21cdd97e0af8c77b0898c21fb"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/e85775299dc94247838d34e5be1d9a677232c9ff","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/e85775299dc94247838d34e5be1d9a677232c9ff","node_id":"C_kwDOUvGM1NoAKGU4NTc3NTI5OWRjOTQyNDc4MzhkMzRlNWJlMWQ5YTY3NzIzMmM5ZmY","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/3b4b8df97140ce6fe00fe97410038d1183f3693e","sha":"3b4b8df97140ce6fe00fe97410038d1183f3693e","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/3b4b8df97140ce6fe00fe97410038d1183f3693e"}],"sha":"e85775299dc94247838d34e5be1d9a677232c9ff","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/e85775299dc94247838d34e5be1d9a677232c9ff"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/3b4b8df97140ce6fe00fe97410038d1183f3693e/comments","commit":{"author":{"date":"2026-09-12T19:08:10Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T19:08:10Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 3: libs/form-renderer (component registry + ConfigDrivenPage)\n\n- fieldComponentRegistry keyed by field.type (''text'' | ''select'' |\n  ''date'') decides which widget renders; field.validator (''ssn'' |\n  ''phone'' | ...) is orthogonal — it decides what checks the value,\n  wired in milestone 4. An ssn field is just a text field with an ssn\n  validator, so it renders through the same TextField as any other\n  text input; documented this explicitly since it''s a deliberate\n  divergence from the spec''s flatter \"text/select/ssn/phone/date\"\n  registry description.\n- <ConfigDrivenPage config={pageConfig}> renders a carrier config\n  page''s Sections -> Fields purely from data (api-client''s PageConfig\n  type), with no per-carrier page ever hand-coded; throws a clear\n  error for an unregistered field type rather than silently skipping\n  a field, tested explicitly.\n- Fixed a real bug found via typecheck: tsconfig.base.json''s \"lib\" is\n  [\"es2022\"] only (no DOM), which is correct for Node libs like\n  api-client but broke ui-components/form-renderer once code actually\n  touched a DOM property (event.currentTarget.value) rather than just\n  passing HTMLInputElement-typed props through unused — added\n  [\"es2022\",\"dom\",\"dom.iterable\"] to both libs'' tsconfig.lib.json/\n  tsconfig.spec.json rather than polluting the shared base config\n  that backend Node projects also extend.\n- nx sync applied to fix stale/missing TS project references.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"3b48389ba9ec2040e74707cd18c52743a8e8b6b3","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/3b48389ba9ec2040e74707cd18c52743a8e8b6b3"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/3b4b8df97140ce6fe00fe97410038d1183f3693e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/3b4b8df97140ce6fe00fe97410038d1183f3693e","node_id":"C_kwDOUvGM1NoAKDNiNGI4ZGY5NzE0MGNlNmZlMDBmZTk3NDEwMDM4ZDExODNmMzY5M2U","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/5eb9c3d41ff3cf64f1c36544055261e5911e8835","sha":"5eb9c3d41ff3cf64f1c36544055261e5911e8835","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/5eb9c3d41ff3cf64f1c36544055261e5911e8835"}],"sha":"3b4b8df97140ce6fe00fe97410038d1183f3693e","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/3b4b8df97140ce6fe00fe97410038d1183f3693e"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/5eb9c3d41ff3cf64f1c36544055261e5911e8835/comments","commit":{"author":{"date":"2026-09-12T18:59:54Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T18:59:54Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 2: libs/ui-components (Tailwind v4 + Radix/shadcn + Storybook)\n\n- Tailwind v4 (CSS-first config, no tailwind.config.js needed) with\n  shadcn/ui-style oklch design tokens (globals.css) and light/dark\n  variants via a .dark class.\n- Atomic structure: atoms/ (Button, Input, Label, Badge, Checkbox,\n  Select — Checkbox/Select/Label on Radix primitives), molecules/\n  (FormField, Card, StepIndicator, FeedbackButtons), organisms/\n  (AppShell, ChatPanelShell) — copy-in shadcn conventions\n  (class-variance-authority + cn() via clsx/tailwind-merge), not an\n  npm design-system dependency.\n- Every component has a colocated Storybook story; verified visually\n  in the browser (not just \"it built\"): Button renders styled,\n  Select''s Radix portal/dropdown/check-indicator actually open and\n  work, AppShell lays out header/progress/footer correctly.\n- FeedbackButtons has real toggle logic (click same choice clears it,\n  switching choices swaps state) — actually unit-tested with RTL,\n  unlike the purely presentational components which rely on Storybook\n  for verification.\n- ui-components'' own eslint.config.mjs excludes storybook-static/\n  (its build output) — without it, ESLint tried to lint the minified\n  bundle and produced 30k+ false errors.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"ddc4e91d9aabf34e683685b802013f2c455c3433","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/ddc4e91d9aabf34e683685b802013f2c455c3433"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/5eb9c3d41ff3cf64f1c36544055261e5911e8835","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/5eb9c3d41ff3cf64f1c36544055261e5911e8835","node_id":"C_kwDOUvGM1NoAKDVlYjljM2Q0MWZmM2NmNjRmMWMzNjU0NDA1NTI2MWU1OTExZTg4MzU","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/d9f0fadfe6f29400aa4f4beb05393d1100a337c5","sha":"d9f0fadfe6f29400aa4f4beb05393d1100a337c5","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/d9f0fadfe6f29400aa4f4beb05393d1100a337c5"}],"sha":"5eb9c3d41ff3cf64f1c36544055261e5911e8835","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/5eb9c3d41ff3cf64f1c36544055261e5911e8835"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"comments_url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/d9f0fadfe6f29400aa4f4beb05393d1100a337c5/comments","commit":{"author":{"date":"2026-09-12T18:36:28Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"comment_count":0,"committer":{"date":"2026-09-12T18:36:28Z","email":"sujithareddymamidala@gmail.com","name":"Abhilash Sandi"},"message":"Milestone 1: libs/api-client\n\n- Result<T, E> ({success, data} / {success:false, error}) instead of\n  throwing, per the spec''s server-action-friendly contract; http.ts''s\n  requestJson wraps fetch, turning both HTTP error responses and\n  network failures into an err Result rather than a thrown exception.\n- rating-service.types.ts mirrors quoteflow-rating-service''s response\n  shapes (deliberately duplicated, not shared as code, since the two\n  repos talk only over HTTP).\n- createRatingServiceClient(baseUrl) covers every Repo 1 endpoint\n  through the quote lifecycle (create/schema/patch/reports/bind/\n  bind-status/bundle-manifest) plus bindEventsUrl() for the SSE\n  connection frontends open directly.\n- Added Husky + lint-staged (prettier on staged files, nx affected -t\n  lint test typecheck diffed against HEAD~1 rather than a base branch,\n  since we commit directly to master) before every commit, matching\n  quoteflow-rating-service''s convention.\n- All cross-file imports needed explicit .js extensions — the\n  workspace''s tsconfig.base.json uses moduleResolution: nodenext,\n  which enforces ESM-style extensioned relative imports even in .ts\n  source.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"36d0e5bfb2d75547084269eea6f5007bf94cc931","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/trees/36d0e5bfb2d75547084269eea6f5007bf94cc931"},"url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/git/commits/d9f0fadfe6f29400aa4f4beb05393d1100a337c5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starred_url":"https://api.github.com/users/sujithareddym/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sujithareddym/subscriptions","type":"User","url":"https://api.github.com/users/sujithareddym","user_view_type":"public"},"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/d9f0fadfe6f29400aa4f4beb05393d1100a337c5","node_id":"C_kwDOUvGM1NoAKGQ5ZjBmYWRmZTZmMjk0MDBhYTRmNGJlYjA1MzkzZDExMDBhMzM3YzU","parents":[{"html_url":"https://github.com/abhilashsandi/quoteflow-apps/commit/f45632ca9c6187da85bbf0bcccc4cc2e56558f77","sha":"f45632ca9c6187da85bbf0bcccc4cc2e56558f77","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/f45632ca9c6187da85bbf0bcccc4cc2e56558f77"}],"sha":"d9f0fadfe6f29400aa4f4beb05393d1100a337c5","url":"https://api.github.com/repos/abhilashsandi/quoteflow-apps/commits/d9f0fadfe6f29400aa4f4beb05393d1100a337c5"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/259992179?v=4","events_url":"https://api.github.com/users/sujithareddym/events{/privacy}","followers_url":"https://api.github.com/users/sujithareddym/followers","following_url":"https://api.github.com/users/sujithareddym/following{/other_user}","gists_url":"https://api.github.com/users/sujithareddym/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sujithareddym","id":259992179,"login":"sujithareddym","node_id":"U_kgDOD38qcw","organizations_url":"https://api.github.com/users/sujithareddym/orgs","received_events_url":"https://api.github.com/users/sujithareddym/received_events","repos_url":"https://api.github.com/users/sujithareddym/repos","site_admin":false,"starr