nt":0,"committer":{"date":"2026-09-29T02:35:04Z","email":"28593727+losnah-think@users.noreply.github.com","name":"Hansol Choi"},"message":"Publish sanitized Gacha frontend and backend source snapshot","tree":{"sha":"4aee9e7d660db4b88afd5279cae814382d1b9000","url":"https://api.github.com/repos/losnah-think/gacha-portfolio/git/trees/4aee9e7d660db4b88afd5279cae814382d1b9000"},"url":"https://api.github.com/repos/losnah-think/gacha-portfolio/git/commits/446257c281e20235a72a65da06286c7b53c76f29","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/28593727?v=4","events_url":"https://api.github.com/users/losnah-think/events{/privacy}","followers_url":"https://api.github.com/users/losnah-think/followers","following_url":"https://api.github.com/users/losnah-think/following{/other_user}","gists_url":"https://api.github.com/users/losnah-think/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/losnah-think","id":28593727,"login":"losnah-think","node_id":"MDQ6VXNlcjI4NTkzNzI3","organizations_url":"https://api.github.com/users/losnah-think/orgs","received_events_url":"https://api.github.com/users/losnah-think/received_events","repos_url":"https://api.github.com/users/losnah-think/repos","site_admin":false,"starred_url":"https://api.github.com/users/losnah-think/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/losnah-think/subscriptions","type":"User","url":"https://api.github.com/users/losnah-think","user_view_type":"public"},"html_url":"https://github.com/losnah-think/gacha-portfolio/commit/446257c281e20235a72a65da06286c7b53c76f29","node_id":"C_kwDOUxhfB9oAKDQ0NjI1N2MyODFlMjAyMzVhNzJhNjVkYTA2Mjg2YzdiNTNjNzZmMjk","parents":[],"sha":"446257c281e20235a72a65da06286c7b53c76f29","url":"https://api.github.com/repos/losnah-think/gacha-portfolio/commits/446257c281e20235a72a65da06286c7b53c76f29"}],"requestUrl":"https://api.github.co