INSERT INTO collection_pages VALUES('121d23d8a8c77057b3efd3c5e38ce090085a9861f794153dcacfbd78dcc3cbd5','ed5bfdd23fbc5a3fa8d1326b021113033bca9a7c893b2cd1f7f72ff6ea9cd4a5','{"hasNext":false,"items":[{"author":{"account":{"login":"dominicgan","providerType":"User"},"email":"dominic.gan@accenture.com","name":"Gan, Dominic"},"authoredDate":"2026-09-29T03:03:55Z","committedDate":"2026-09-29T03:03:55Z","committer":{"account":{"login":"dominicgan","providerType":"User"},"email":"dominic.gan@accenture.com","name":"Gan, Dominic"},"observedAt":"2026-10-09T00:51:50.379Z","repositoryId":1394129674,"sha":"1054d98d41d9d4258877ac565e51fa567a70834e"}],"observedAt":"2026-10-09T00:51:50.379Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/7966311?v=4","events_url":"https://api.github.com/users/dominicgan/events{/privacy}","followers_url":"https://api.github.com/users/dominicgan/followers","following_url":"https://api.github.com/users/dominicgan/following{/other_user}","gists_url":"https://api.github.com/users/dominicgan/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dominicgan","id":7966311,"login":"dominicgan","node_id":"MDQ6VXNlcjc5NjYzMTE=","organizations_url":"https://api.github.com/users/dominicgan/orgs","received_events_url":"https://api.github.com/users/dominicgan/received_events","repos_url":"https://api.github.com/users/dominicgan/repos","site_admin":false,"starred_url":"https://api.github.com/users/dominicgan/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dominicgan/subscriptions","type":"User","url":"https://api.github.com/users/dominicgan","user_view_type":"public"},"comments_url":"https://api.github.com/repos/dominicgan/mfe-owasp-dependency-viewer/commits/1054d98d41d9d4258877ac565e51fa567a70834e/comments","commit":{"author":{"date":"2026-09-29T03:03:55Z","email":"dominic.gan@accenture.com","name":"Gan, Dominic"},"comment_count":0,"committer":{"date":"2026-09-29T03:03:55Z","email":"dominic.gan@accenture.com","name":"Gan, Dominic"},"message":"Add MFE dependency report viewer\n\nA browser-based viewer that pools OWASP dependency-check JSON reports from\nevery micro-frontend into one dashboard, so the question becomes \"which\nhandful of version bumps clears most of this\" rather than \"how many findings\ndoes each team have\".\n\nThe load-bearing piece is how a fixed version is derived. Every advisory\ncarries a machine-readable CPE range, and an exclusive upper bound (<3.1.6)\nis a statement that 3.1.6 is clean, while an inclusive one (<=10.4.0) is not.\nThose are kept as distinct fix states, the advisory''s prose is never parsed,\nand each derived fix records the range it came from. A package''s target is\nthe strongest constraint across all its advisories, so Remediation gives one\nnumber per package rather than a per-advisory list to reconcile by hand.\n\nViews: Overview (led by the cumulative remediation curve), Remediation (one\nrow per package, sorted by findings closed), By MFE (shared vs only-here\ndebt), By advisory, and the full findings grid. Faceted filtering is\nsingle-pass, filter state lives in the URL, and the loaded set persists in\nIndexedDB so a reload is not a re-upload.\n\nReports are identified by projectInfo.name and renameable; identical bytes\nare ignored, a newer scan of the same MFE replaces the old one, and an older\none replaces but warns. Scan age is surfaced throughout, since reports taken\nweeks apart were measured against different advisory databases.\n\nAdvisory links are GHSA-aware: NVD and MITRE cannot resolve a GHSA, so those\nlinks are not offered on those rows and OSV is the default. Hover enrichment\nfrom OSV and EPSS is opt-out and sends only the identifier.\n\nnpm run verify parses a set of reports outside the UI and asserts the\ndeterminism contract, including that every derived fix version really does\nfall outside the range it was derived from.\n\nBuilt on the patterns in myexp-prisma-report-explorer: Vite + React 19,\nTailwind v4, vendored shadcn/ui, ag-grid, Recharts. The dashboard sits behind\na lazy boundary so ag-grid and Recharts are not fetched to paint the upload\nscreen.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"174faf8bef918f12b8ed0400c6ef1e2eaeae398a","url":"https://api.github.com/repos/dominicgan/mfe-owasp-dependency-viewer/git/trees/174faf8bef918f12b8ed0400c6ef1e2eaeae398a"},"url":"https://api.github.com/repos/dominicgan/mfe-owasp-dependency-viewer/git/commits/1054d98d41d9d4258877ac565e51fa567a70834e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/7966311?v=4","events_url":"https://api.github.com/users/dominicgan/events{/privacy}","followers_url":"https://api.github.com/users/dominicgan/followers","following_url":"https://api.github.com/users/dominicgan/following{/other_user}","gists_url":"https://api.github.com/users/dominicgan/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dominicgan","id":7966311,"login":"dominicgan","node_id":"MDQ6VXNlcjc5NjYzMTE=","organizations_url":"https://api.github.com/users/dominicgan/orgs","received_events_url":"https://api.github.com/users/dominicgan/received_events","repos_url":"https://api.github.com/users/dominicgan/repos","site_admin":false,"starred_url":"https://api.github.com/users/dominicgan/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dominicgan/subscriptions","type":"User","url":"https://api.github.com/users/dominicgan","user_view_type":"public"},"html_url":"https://github.com/dominicgan/mfe-owasp-dependency-viewer/commit/1054d98d41d9d4258877ac565e51fa567a70834e","node_id":"C_kwDOUxi7CtoAKDEwNTRkOThkNDFkOWQ0MjU4ODc3YWM1NjVlNTFmYTU2N2E3MDgzNGU","parents":[],"sha":"1054d98d41d9d4258877ac565e51fa567a70834e","url":"https://api.github.com/repos/dominicgan/mfe-owasp-dependency-viewer/commits/1054d98d41d9d4258877ac565e51fa567a70834e"}],"requestUrl":"https://api.github.com/repos/dominicgan/mfe-owasp-dependency-viewer/commits?per_page=100&page=1&sha=1054d98d41d9d4258877ac565e51fa567a70834e&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A02%3A26.752Z"}');
